-- Delete all rows from 2017
DELETE FROM production.product_history
WHERE  model_year = 2017;

-- Delete a specific number of rows
DELETE TOP (10) FROM production.product_history;

BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE sales.accounts
    SET    balance = balance - 100
    WHERE  account_id = 12345;

    UPDATE sales.accounts
    SET    balance = balance + 100
    WHERE  account_id = 67890;

    COMMIT TRANSACTION;
    PRINT 'Transfer complete.';
END TRY
BEGIN CATCH
    ROLLBACK TRANSACTION;
    PRINT 'Transfer failed — all changes rolled back.';
END CATCH;
